public void update(float delta) {
    if (currentCooldown > 0) {
        currentCooldown -= delta;
        if (currentCooldown < 0) currentCooldown = 0;
    }

    if (isCasting) {
        castTimer += delta;
        if (castTimer >= castTime) {
            onCastComplete();
            isCasting = false;
            castTimer = 0f;
        }
    }
}
